        let mut d = vec![0; n];
        for (i, &v) in lights.iter().enumerate() {
            if v > 0 {
                let l = 0.max(i as i32 - v) as usize;
                let r = (n as i32 - 1).min(i as i32 + v) as usize;
                d[l] += 1;
                if r + 1 < n {
                    d[r + 1] -= 1;
                }
            }
        }
        let (mut s, mut cnt, mut ans) = (0, 0, 0);
        for x in d {
            s += x;
            if s == 0 {
                cnt += 1;
            } else {
